export function PlaceholderBlur({
  blurAmount = {{blurAmount}},
  theme = "{{theme}}",
  transitionMs = {{transitionMs}},
  caption = {{caption}},
}) {
  const swatch = { mint: "#A8E6C1", sky: "#BFD9F2", blush: "#F5C2E0" }[theme] ?? "#A8E6C1";
  return (
    <div>
      {/* In production, remove the blur filter and swap in the full-resolution <img> on its "load" event. */}
      <figure className="ph-blur-react" style={{ margin: 0, maxWidth: 320, aspectRatio: "8 / 5", borderRadius: 10, overflow: "hidden",
        color: swatch, filter: `blur(${blurAmount}px)`, "--ph-blur-ms": `${transitionMs}ms` }}>
        <svg viewBox="0 0 320 200" width="100%" height="100%" role="img" aria-label="Placeholder preview while the full image loads">
          <rect width="320" height="200" fill="currentColor" />
        </svg>
      </figure>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .ph-blur-react { transition: filter var(--ph-blur-ms) ease; }
        }
      `}</style>
      {caption && (
        <p style={{ margin: "8px 2px 0", font: "12px/1.4 system-ui, sans-serif", color: "#24143099", maxWidth: 320 }}>
          Low-quality placeholder shown while the full image loads.
        </p>
      )}
    </div>
  );
}
